public class F {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        int n = Integer.parseInt(parts[0]);
        int K = Integer.parseInt(parts[1]);
        int L = Integer.parseInt(parts[2]);
        int mod = 998244353;
        int[][] fif = enumFIF(10000, mod);
        long[] muls = new long[n + 1];
        for (int i = K; i <= n; i++) {
            long m = C(n, i, mod, fif);
            for (int j = i; j <= n; j++) {
                long sign = ((j - i) % 2 == 0) ? 1 : -1;
                muls[j] += m * C(n - i, n - j, mod, fif) * sign;
                muls[j] %= mod;
            }
        }
        long ans = 0;
        for (int i = K; i <= n; i++) {
            long term = pow(2, i, mod) * fif[0][i] % mod * fif[0][i] % mod
                    * fif[1][2 * i + 1] % mod * muls[i];
            ans += term;
            ans %= mod;
        }
        if (ans < 0) ans += mod;
        System.out.println(ans * L % mod);
    }

    public static long C(int n, int r, int mod, int[][] fif) {
        if (n < 0 || r < 0 || r > n) return 0;
        return (long) fif[0][n] * fif[1][r] % mod * fif[1][n - r] % mod;
    }

    public static long pow(long a, int n, int mod) {
        long res = 1;
        long base = a % mod;
        for (int i = 0; i < n; i++) {
            res = res * base % mod;
        }
        return res;
    }

    public static int[][] enumFIF(int n, int mod) {
        int[] f = new int[n + 1];
        int[] invf = new int[n + 1];
        f[0] = 1;
        for (int i = 1; i <= n; i++) {
            f[i] = (int) ((long) f[i - 1] * i % mod);
        }
        long a = f[n];
        long b = mod;
        long p = 1, q = 0;
        while (b > 0) {
            long c = a / b;
            long d = a;
            a = b;
            b = d % b;
            d = p;
            p = q;
            q = d - c * q;
        }
        invf[n] = (int) (p < 0 ? p + mod : p);
        for (int i = n - 1; i >= 0; i--) {
            invf[i] = (int) ((long) invf[i + 1] * (i + 1) % mod);
        }
        return new int[][] { f, invf };
    }
}
