#include <bits/stdc++.h>
using namespace std;

long long C(int n, int r, int mod, vector<long long>& fact, vector<long long>& invFact) {
    if (n < 0 || r < 0 || r > n) return 0;
    return fact[n] * invFact[r] % mod * invFact[n - r] % mod;
}

long long pow_mod(long long a, int n, int mod) {
    long long res = 1;
    long long base = a % mod;
    for (int i = 0; i < n; i++) {
        res = res * base % mod;
    }
    return res;
}

void enumFIF(int n, int mod, vector<long long>& fact, vector<long long>& invFact) {
    fact.resize(n + 1);
    invFact.resize(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; i++) {
        fact[i] = fact[i - 1] * i % mod;
    }
    long long a = fact[n];
    long long b = mod;
    long long p = 1, q = 0;
    while (b > 0) {
        long long c = a / b;
        long long d = a;
        a = b;
        b = d % b;
        d = p;
        p = q;
        q = d - c * q;
    }
    invFact[n] = (p < 0 ? p + mod : p);
    for (int i = n - 1; i >= 0; i--) {
        invFact[i] = invFact[i + 1] * (i + 1) % mod;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, K, L;
    cin >> n >> K >> L;
    const int mod = 998244353;
    vector<long long> fact, invFact;
    enumFIF(10000, mod, fact, invFact);
    vector<long long> muls(n + 1, 0);
    for (int i = K; i <= n; i++) {
        long long m = C(n, i, mod, fact, invFact);
        for (int j = i; j <= n; j++) {
            long long sign = ((j - i) % 2 == 0) ? 1 : -1;
            long long val = m * C(n - i, n - j, mod, fact, invFact) % mod * sign;
            muls[j] = (muls[j] + val) % mod;
        }
    }
    long long ans = 0;
    for (int i = K; i <= n; i++) {
        long long term = pow_mod(2, i, mod) * fact[i] % mod * invFact[i] % mod
                * fact[2 * i + 1] % mod * muls[i] % mod;
        ans = (ans + term) % mod;
    }
    ans = (ans + mod) % mod;
    cout << (ans * L) % mod << "\n";
    return 0;
}

